import{_ as e,o as a,c as d,a2 as r}from"./chunks/framework.CyZTVJbV.js";const p=JSON.parse('{"title":"Mock Design Spec (日本語)","description":"","frontmatter":{},"headers":[],"relativePath":"MOCK-DESIGN.ja.md","filePath":"MOCK-DESIGN.ja.md"}'),l={name:"MOCK-DESIGN.ja.md"};function o(i,t,n,s,h,c){return a(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="mock-design-spec-日本語" tabindex="-1">Mock Design Spec (日本語) <a class="header-anchor" href="#mock-design-spec-日本語" aria-label="Permalink to &quot;Mock Design Spec (日本語)&quot;">​</a></h1><blockquote><p><a href="./MOCK-DESIGN">🇬🇧 English</a> • <a href="./MOCK-DESIGN.ja">🇯🇵 日本語</a></p></blockquote><p>kiwa がサードパーティ wallet / AA SDK (WalletConnect / Safe / thirdweb / Privy / Biconomy ...) に対して <strong>何をどこまで mock するか</strong> を決める仕様書。 Phase D-3 の実装 PR が参照する SSOT。</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>各 wallet / SDK は 5 観点のスコアリングに基づいて <strong>3 段階の mock 精度 level</strong> に分類する。 分類によって実 SDK を採用 (Level A)、 compatible mock を出す (Level B)、 behavioral pattern だけ示す (Level C) かを判定する。</p><table tabindex="0"><thead><tr><th>Level</th><th>アプローチ</th><th>SDK 依存</th><th>精度</th><th>維持コスト</th></tr></thead><tbody><tr><td><strong>A — Real SDK Integration</strong></td><td><code>peerDependencies</code> + 選択的 stub (relay / bundler / paymaster)</td><td>あり</td><td>高</td><td>高 (SDK breaking change 追従)</td></tr><tr><td><strong>B — Compatible Mock</strong></td><td>SDK の public interface を模倣、 内部実装は mock</td><td>なし</td><td>中</td><td>中</td></tr><tr><td><strong>C — Behavioral Pattern</strong></td><td>抽象的振る舞い pattern のみ提示 (multi-sig / embedded wallet 等)</td><td>なし</td><td>低</td><td>低</td></tr></tbody></table><hr><h2 id="なぜこの仕様書が必要か" tabindex="-1">なぜこの仕様書が必要か <a class="header-anchor" href="#なぜこの仕様書が必要か" aria-label="Permalink to &quot;なぜこの仕様書が必要か&quot;">​</a></h2><p>実 dApp 利用者は MetaMask 以外に Safe / thirdweb inAppWallet / Biconomy / WalletConnect v2 を多用する。 「全部を忠実に mock する」 が一見良さげに見えるが以下の問題が起きる:</p><ul><li>SDK の breaking change で fixture が四半期ごとに腐る</li><li>install size が爆発する (Web3Auth / Pimlico 等は数 100 KB)</li><li>mock と実 SDK の挙動差で偽陽性混入</li></ul><p>維持可能性を保つため、 新 wallet / SDK の要望が来るたびに <strong>判断プロトコル</strong> が必要。</p><h2 id="_5-観点スコアリング" tabindex="-1">5 観点スコアリング <a class="header-anchor" href="#_5-観点スコアリング" aria-label="Permalink to &quot;5 観点スコアリング&quot;">​</a></h2><p>新 wallet / SDK 候補ごとに以下 5 観点で 0/1 をスコア。 <strong>合計値が精度 level を決める</strong>。</p><table tabindex="0"><thead><tr><th>#</th><th>観点</th><th>+1 条件</th></tr></thead><tbody><tr><td>1</td><td>SDK API stability</td><td>minor 改修が四半期に 1 回以下</td></tr><tr><td>2</td><td>利用者数</td><td>月間 active dApp &gt; 10k</td></tr><tr><td>3</td><td>SDK 自体の test mode</td><td>SDK が公式に test fixture / sandbox を提供</td></tr><tr><td>4</td><td>install size 影響</td><td>peerDeps 追加で gzipped &lt; 500 KB</td></tr><tr><td>5</td><td>use case 数</td><td>dApp test で意味のある pattern 3+ (sign / send / multi-account / paymaster ...)</td></tr></tbody></table><p><strong>合計</strong> → 精度 level:</p><ul><li><strong>3+</strong> → Level A (Real SDK Integration)</li><li><strong>1–2</strong> → Level B (Compatible Mock)</li><li><strong>0</strong> → Level C (Behavioral Pattern)</li></ul><p>境界 case (ちょうど 3 点) は install size の重さが主リスクなら Level B を推奨。</p><h2 id="wallet-sdk-分類-初期配分" tabindex="-1">Wallet / SDK 分類 (初期配分) <a class="header-anchor" href="#wallet-sdk-分類-初期配分" aria-label="Permalink to &quot;Wallet / SDK 分類 (初期配分)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Wallet / SDK</th><th>API stability</th><th>利用者数</th><th>test mode</th><th>size</th><th>use case</th><th><strong>合計</strong></th><th><strong>Level</strong></th><th>根拠</th></tr></thead><tbody><tr><td><strong>WalletConnect v2</strong></td><td>+1</td><td>+1</td><td>+1</td><td>+1</td><td>+1</td><td><strong>5</strong></td><td><strong>A</strong></td><td>利用者最多、 spec 安定、 公式 test wallet あり、 size 中</td></tr><tr><td><strong>Safe (Gnosis Safe)</strong></td><td>+1</td><td>+1</td><td>0</td><td>+1</td><td>0</td><td><strong>3</strong></td><td><strong>B</strong> (境界)</td><td>API 安定だが SDK が重い、 mock contract で等価カバー可</td></tr><tr><td><strong>thirdweb inAppWallet</strong></td><td>0</td><td>+1</td><td>0</td><td>0</td><td>+1</td><td><strong>2</strong></td><td><strong>B</strong></td><td>API 進化中、 bundle 大、 behavioral mock の方が安全</td></tr><tr><td><strong>Privy / Dynamic</strong></td><td>0</td><td>+1</td><td>0</td><td>0</td><td>0</td><td><strong>1</strong></td><td><strong>B</strong></td><td>embedded-wallet pattern が SDK 仕様より重要</td></tr><tr><td><strong>Biconomy / ZeroDev / Alchemy AA</strong></td><td>0</td><td>+1</td><td>0</td><td>0</td><td>+1</td><td><strong>2</strong></td><td><strong>B</strong></td><td>bundler / paymaster 挙動を SDK 依存なしで mock 可</td></tr><tr><td><strong>Coinbase Wallet</strong></td><td>+1</td><td>+1</td><td>+1</td><td>+1</td><td>0</td><td><strong>4</strong></td><td><strong>A</strong></td><td>既に EIP-6963 announce で対応済、 追加作業不要</td></tr><tr><td><strong>Ledger / Trezor</strong></td><td>+1</td><td>0</td><td>0</td><td>0</td><td>0</td><td><strong>1</strong></td><td><strong>対応外</strong></td><td>HID / Bluetooth mock は非実用、 実 device test 別ツールへ</td></tr><tr><td><strong>Phantom (EVM mixed)</strong></td><td>0</td><td>0</td><td>0</td><td>0</td><td>0</td><td><strong>0</strong></td><td><strong>対応外</strong></td><td>Solana primary、 EVM scope 限定維持</td></tr></tbody></table><h2 id="level-a-—-real-sdk-integration" tabindex="-1">Level A — Real SDK Integration <a class="header-anchor" href="#level-a-—-real-sdk-integration" aria-label="Permalink to &quot;Level A — Real SDK Integration&quot;">​</a></h2><h3 id="kiwa-が提供するもの" tabindex="-1">kiwa が提供するもの <a class="header-anchor" href="#kiwa-が提供するもの" aria-label="Permalink to &quot;kiwa が提供するもの&quot;">​</a></h3><ul><li>該当 wallet / SDK を <code>peerDependencies</code> に追加 (利用者は自分で install)</li><li>kiwa fixture が SDK の標準 entry point を wrap</li><li>外部 infra (relay / bundler / paymaster) 依存部だけ stub 化</li></ul><h3 id="kiwa-が提供しないもの" tabindex="-1">kiwa が提供しないもの <a class="header-anchor" href="#kiwa-が提供しないもの" aria-label="Permalink to &quot;kiwa が提供しないもの&quot;">​</a></h3><ul><li>SDK の public API の再実装</li><li>SDK を別名で隠蔽</li></ul><h3 id="例フロー-walletconnect-v2" tabindex="-1">例フロー (WalletConnect v2) <a class="header-anchor" href="#例フロー-walletconnect-v2" aria-label="Permalink to &quot;例フロー (WalletConnect v2)&quot;">​</a></h3><ol><li>利用者が自分で <code>@walletconnect/web3wallet</code> を install</li><li>kiwa が in-memory relay stub を提供 (実 WalletConnect cloud project 不要)</li><li>利用者は test 内で <code>walletKit.pair(...)</code> を実 wallet 接続と同じ書き方で呼ぶ</li><li>kiwa が session proposal / response を stub 経由でルーティング</li></ol><h3 id="trade-offs" tabindex="-1">Trade-offs <a class="header-anchor" href="#trade-offs" aria-label="Permalink to &quot;Trade-offs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>利点</th><th>欠点</th></tr></thead><tbody><tr><td>実 SDK bug が再現できる</td><td>四半期 SDK 更新で test 壊れる可能性</td></tr><tr><td>test が production code と同じ書き方</td><td>install size 増</td></tr><tr><td>SDK 公式 docs と整合</td><td>SDK 入れられない利用者には届かない</td></tr></tbody></table><h2 id="level-b-—-compatible-mock" tabindex="-1">Level B — Compatible Mock <a class="header-anchor" href="#level-b-—-compatible-mock" aria-label="Permalink to &quot;Level B — Compatible Mock&quot;">​</a></h2><h3 id="kiwa-が提供するもの-1" tabindex="-1">kiwa が提供するもの <a class="header-anchor" href="#kiwa-が提供するもの-1" aria-label="Permalink to &quot;kiwa が提供するもの&quot;">​</a></h3><ul><li>実 SDK と <strong>同じ TypeScript interface</strong> を粗いレベルで提供する mock module</li><li>内部実装は kiwa contributors が書く (mock contract deploy + deterministic data 返却)</li></ul><h3 id="kiwa-が提供しないもの-1" tabindex="-1">kiwa が提供しないもの <a class="header-anchor" href="#kiwa-が提供しないもの-1" aria-label="Permalink to &quot;kiwa が提供しないもの&quot;">​</a></h3><ul><li>上流 SDK の minor / patch release を逐一追従</li><li>production tx との bit 単位互換性</li></ul><h3 id="例フロー-safe" tabindex="-1">例フロー (Safe) <a class="header-anchor" href="#例フロー-safe" aria-label="Permalink to &quot;例フロー (Safe)&quot;">​</a></h3><ol><li>kiwa が <code>examples/nextjs-safe-multisig/</code> で Safe contract を自前 deploy (threshold + module + guard 振る舞いを再現)</li><li>fixture で <code>useSafe()</code> 風 hook を <code>@safe-global/safe-react-hooks</code> と同じ shape で提供</li><li>multi-sig threshold sign / module execution / guard reject を mock contract に対して test</li><li>production 移行時は import を実 <code>@safe-global/safe-react-hooks</code> に差し替えるだけ</li></ol><h3 id="trade-offs-1" tabindex="-1">Trade-offs <a class="header-anchor" href="#trade-offs-1" aria-label="Permalink to &quot;Trade-offs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>利点</th><th>欠点</th></tr></thead><tbody><tr><td>SDK 依存なし、 install size 小</td><td>mock と実 SDK が時間とともに乖離する可能性</td></tr><tr><td>維持コスト安定</td><td>実 SDK 固有 quirk が再現できないと偽陽性リスク</td></tr><tr><td>CI flake 解消には十分忠実</td><td>production bug 再現は限定的</td></tr></tbody></table><h2 id="level-c-—-behavioral-pattern" tabindex="-1">Level C — Behavioral Pattern <a class="header-anchor" href="#level-c-—-behavioral-pattern" aria-label="Permalink to &quot;Level C — Behavioral Pattern&quot;">​</a></h2><h3 id="kiwa-が提供するもの-2" tabindex="-1">kiwa が提供するもの <a class="header-anchor" href="#kiwa-が提供するもの-2" aria-label="Permalink to &quot;kiwa が提供するもの&quot;">​</a></h3><ul><li>wallet カテゴリの <strong>形</strong> を抽出した汎用 helper / pattern (例: 「multi-sig threshold sign」「embedded wallet with key escrow」)</li><li>特定 SDK 名は出さない</li></ul><h3 id="kiwa-が提供しないもの-2" tabindex="-1">kiwa が提供しないもの <a class="header-anchor" href="#kiwa-が提供しないもの-2" aria-label="Permalink to &quot;kiwa が提供しないもの&quot;">​</a></h3><ul><li>名前付き SDK との drop-in 互換性</li><li>実 SDK bug の検出保証</li></ul><h3 id="例フロー-privy-dynamic-embedded-wallet" tabindex="-1">例フロー (Privy / Dynamic embedded wallet) <a class="header-anchor" href="#例フロー-privy-dynamic-embedded-wallet" aria-label="Permalink to &quot;例フロー (Privy / Dynamic embedded wallet)&quot;">​</a></h3><p>kiwa は「embedded wallet」の汎用 pattern (private key を server-side 保管、 signature 要求は stub auth endpoint 経由で round-trip) を Privy / Dynamic と名指しせず documentation する。 利用者は自分の SDK に pattern を読み替える。</p><h3 id="trade-offs-2" tabindex="-1">Trade-offs <a class="header-anchor" href="#trade-offs-2" aria-label="Permalink to &quot;Trade-offs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>利点</th><th>欠点</th></tr></thead><tbody><tr><td>維持負荷最低</td><td>利用者が自分の SDK に読み替える必要</td></tr><tr><td>SDK 変動に強い</td><td>実 SDK 固有挙動は見えない</td></tr><tr><td>教材性も兼ねる</td><td>「Safe drop-in 対応」より魅力低い</td></tr></tbody></table><h2 id="偽陽性の境界" tabindex="-1">偽陽性の境界 <a class="header-anchor" href="#偽陽性の境界" aria-label="Permalink to &quot;偽陽性の境界&quot;">​</a></h2><p>各 level で実環境との既知差分を documentation する。 利用者が「kiwa で十分か、 実 infra での staging test も必要か」を判断できるようにする。</p><table tabindex="0"><thead><tr><th>境界</th><th>Level A</th><th>Level B</th><th>Level C</th></tr></thead><tbody><tr><td>実 relay network 失敗 (timeout / drop)</td><td>❌ in-memory stub only</td><td>❌ N/A</td><td>❌ N/A</td></tr><tr><td>実 bundler policy 違反 revert</td><td>❌ stub bundler は全許可</td><td>❌ 同上</td><td>❌ 同上</td></tr><tr><td>実 paymaster gas 推定 error</td><td>❌ paymaster 寛容に mock</td><td>❌ 同上</td><td>❌ 同上</td></tr><tr><td>smart account upgrade hook</td><td>✅ 実 SDK 経由</td><td>⚠️ mock 精度依存</td><td>❌ pattern only</td></tr><tr><td>RPC provider rate limit</td><td>❌ 再現不可</td><td>❌ 同上</td><td>❌ 同上</td></tr></tbody></table><p>これらの境界を検証したい利用者は kiwa CI に加えて <strong>実 testnet での staging test</strong> を実施する。</p><h2 id="新-wallet-sdk-追加時の判定手順" tabindex="-1">新 wallet / SDK 追加時の判定手順 <a class="header-anchor" href="#新-wallet-sdk-追加時の判定手順" aria-label="Permalink to &quot;新 wallet / SDK 追加時の判定手順&quot;">​</a></h2><ol><li>候補を 5 観点でスコア</li><li>対応 level を選択 (A / B / C)</li><li>issue を <code>feat(wallet-support): &lt;name&gt; at Level &lt;X&gt;</code> タイトルで起票し <code>wallet-support</code> label</li><li>Phase D maintainer が 1 週間以内にスコアレビュー</li><li>実装 PR は本仕様書を description で参照</li></ol><h2 id="roadmap" tabindex="-1">Roadmap <a class="header-anchor" href="#roadmap" aria-label="Permalink to &quot;Roadmap&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Phase</th><th>Scope</th><th>対象</th></tr></thead><tbody><tr><td><strong>D-3a</strong></td><td>WalletConnect v2 を Level A で</td><td><code>examples/nextjs-walletconnect-v2/</code></td></tr><tr><td><strong>D-3b</strong></td><td>Safe を Level B で</td><td><code>examples/nextjs-safe-multisig/</code></td></tr><tr><td><strong>D-3c</strong></td><td>thirdweb を Level B で</td><td><code>examples/nextjs-thirdweb-aa/</code></td></tr><tr><td><strong>D-3d</strong></td><td>Privy / Dynamic を Level C で</td><td>docs cookbook 章のみ</td></tr><tr><td><strong>D-3e</strong></td><td>Biconomy / ZeroDev / Alchemy を Level B で</td><td><code>examples/nextjs-aa-paymaster/</code></td></tr><tr><td><strong>D-4</strong></td><td>mainnet fork での AA full flow</td><td><code>examples/nextjs-aa-mainnet-fork/</code></td></tr></tbody></table><p>Phase 順は実装難易度ではなく <strong>利用者数</strong> で決める。 WalletConnect v2 が最初なのは最大母数を unlock するため。</p><h2 id="関連" tabindex="-1">関連 <a class="header-anchor" href="#関連" aria-label="Permalink to &quot;関連&quot;">​</a></h2><ul><li><a href="./COMPARISON"><code>docs/COMPARISON.md</code></a> — Synpress / wallet-mock との使い分け</li><li><a href="./../.claude/skills/kiwa-play/references/adversarial-pitfalls"><code>.claude/skills/kiwa-play/references/adversarial-pitfalls.md</code></a> — 偽陽性パターン 9 種 + self-check</li><li><a href="./ja/cookbook/smart-wallet-aa"><code>docs/ja/cookbook/smart-wallet-aa.md</code></a> — 既存 AA (ERC-4337) test pattern</li></ul>',57)])])}const g=e(l,[["render",o]]);export{p as __pageData,g as default};
